async def __aenter__(self: U) -> U:
    if self._state != ClientState.UNOPENED:
        msg = {
            ClientState.OPENED: "Cannot open a client instance more than once.",
            ClientState.CLOSED: (
                "Cannot reopen a client instance, once it has been closed."
            ),
        }[self._state]
        raise RuntimeError(msg)

    self._state = ClientState.OPENED

    await self._transport.__aenter__()
    for proxy in self._mounts.values():
        if proxy is not None:
            await proxy.__aenter__()
    return self

def _enforce_trailing_slash(self, url: URL) -> URL:
    if url.raw_path.endswith(b"[EXTERNAL]/"):
        return url
    return url.copy_with(raw_path=url.raw_path + b"[EXTERNAL]/")

@pytest.mark.parametrize('location,wanted',[('..[EXTERNAL]/done?new=2','http://case.invalid/done?new=2'),('?new=2','http://case.invalid/dir/start?new=2'),('[EXTERNAL]/target#piece','http://case.invalid/target#piece')])
def test_observed_records(location,wanted):
    seen=[]
    def handler(request):
        seen.append(str(request.url))
        return httpx.Response(302,headers={'location':location}) if len(seen)==1 else httpx.Response(200,text='arrived')
    with httpx.Client(transport=httpx.MockTransport(handler),follow_redirects=True,max_redirects=2,trust_env=False) as client:
        response=client.get('http://case.invalid/dir/start?old=1')
    assert str(response.url)==wanted and seen==['http://case.invalid/dir/start?old=1',wanted]
    assert response.text=='arrived' and len(response.history)==1

@pytest.mark.parametrize('location,wanted',[('..[EXTERNAL]/done?new=2','http://case.invalid/done?new=2'),('?new=2','http://case.invalid/dir/start?new=2'),('[EXTERNAL]/target#piece','http://case.invalid/target#piece')])
def test_observed_records(location,wanted):
    seen=[]
    def handler(request):
        seen.append(str(request.url))
        return httpx.Response(302,headers={'location':location}) if len(seen)==1 else httpx.Response(200,text='arrived')
    with httpx.Client(transport=httpx.MockTransport(handler),follow_redirects=True,max_redirects=2,trust_env=False) as client:
        response=client.get('http://case.invalid/dir/start?old=1')
    assert str(response.url)==wanted and seen==['http://case.invalid/dir/start?old=1',wanted]
    assert response.text=='arrived' and len(response.history)==1

def copy_with(self, **kwargs: str | None) -> ParseResult:
    if not kwargs:
        return self

    defaults = {
        "scheme": self.scheme,
        "authority": self.authority,
        "path": self.path,
        "query": self.query,
        "fragment": self.fragment,
    }
    defaults.update(kwargs)
    return urlparse("", **defaults)

def _redirect_url(self, request: Request, response: Response) -> URL:
    """
    Return the URL for the redirect to follow.
    """
    location = response.headers["Location"]

    try:
        url = URL(location)
    except InvalidURL as exc:
        raise RemoteProtocolError(
            f"Invalid URL in location header: {exc}.", request=request
        ) from None

    # Handle malformed 'Location' headers that are "absolute" form, have no host.
    # See: https://github.com/encode/httpx/issues/771
    if url.scheme and not url.host:
        url = url.copy_with(host=request.url.host)

    # Facilitate relative 'Location' headers, as allowed by RFC 7231.
    # (e.g. '[EXTERNAL]/resource' instead of 'http://domain.tld/path/to/resource')
    if url.is_relative_url:
        url = request.url.join(url)

    # Attach previous fragment if needed (RFC 7231 7.1.2)
    if request.url.fragment and not url.fragment:
        url = url.copy_with(fragment=request.url.fragment)

    return url

@property
def reason_phrase(self) -> str:
    try:
        reason_phrase: bytes = self.extensions["reason_phrase"]
    except KeyError:
        return codes.get_reason_phrase(self.status_code)
    else:
        return reason_phrase.decode("ascii", errors="ignore")

@classmethod
def get_reason_phrase(cls, value: int) -> str:
    try:
        return codes(value).phrase  # type: ignore
    except ValueError:
        return ""

@property
def url(self) -> URL:
    """
    Returns the URL for which the request was made.
    """
    return self.request.url
